2:  * Gaps between her bubbles only. Nothing is added before the first one, because
3:  * Mistral already spends 1 to 5 seconds there and a human would have been typing
4:  * through it.
5:  *
6:  * Target band: 3–10s by next-bubble length (Doc locked 2026-08-01).
7:  */
8: export const PACE_BUDGET_MS = 20_000;
9: 
10: const MIN_MS = 3_000;
11: const MAX_MS = 10_000;
12: 
13: /**
14:  * `tempoGapMs` is how long Doc took to send this message after his previous one.
15:  * Char length dominates; rapid-fire from him slightly shortens the band.
16:  */
17: export function bubbleDelayMs(params: {
18:   tempoGapMs: number | null;
19:   chars: number;
20:   remainingBudgetMs: number;
21:   rand?: () => number;
22: }): number {
23:   if (params.remainingBudgetMs <= 0) return 0;
24:   const rand = params.rand ?? Math.random;
25:   const t = Math.min(1, Math.max(0, params.chars / 280));
26:   const base = MIN_MS + t * (MAX_MS - MIN_MS);
27:   const jitter = (rand() - 0.5) * 900;
28:   let tempoScale = 1;
29:   if (params.tempoGapMs !== null && params.tempoGapMs <= 20_000) {
30:     tempoScale = 0.9;
31:   } else if (params.tempoGapMs !== null && params.tempoGapMs > 120_000) {
32:     tempoScale = 1.08;
33:   }
34:   const ms = Math.round(
35:     Math.min(MAX_MS, Math.max(MIN_MS, (base + jitter) * tempoScale)),
36:   );
37:   return Math.min(ms, params.remainingBudgetMs);
38: }
