40: export function sleepAbortable(ms: number, signal: AbortSignal): Promise<void> {
41:   if (ms <= 0 || signal.aborted) return Promise.resolve();
42:   return new Promise((resolve) => {
43:     const timer = setTimeout(finish, ms);
44:     signal.addEventListener("abort", finish, { once: true });
45:     function finish(): void {
46:       clearTimeout(timer);
47:       signal.removeEventListener("abort", finish);
48:       resolve();
49:     }
50:   });
51: }
