53: /** Per-channel record of how fast Doc is going. */
54: export class TempoTracker {
55:   private readonly last = new Map<string, number>();
56:   private readonly gaps = new Map<string, number | null>();
57: 
58:   /** Gap since his previous message, then remembers this one. */
59:   mark(channelId: string, now = Date.now()): number | null {
