1: export type JobContext = { signal: AbortSignal };
2: type Job = (ctx: JobContext) => Promise<void>;
3: 
4: /**
5:  * Serial per channel, and abortable. Abort does not mean "throw the rest away":
6:  * agent-service has already committed her reply to memory, so a swallowed bubble
7:  * is a message the DB thinks she said and Doc never saw. Delivery code treats an
8:  * abort as "stop pacing, send the rest now".
9:  */
10: export class ChannelQueue {
11:   private readonly tails = new Map<string, Promise<void>>();
12:   private readonly running = new Map<string, AbortController>();
13: 
14:   enqueue(channelId: string, job: Job): Promise<void> {
15:     const prev = this.tails.get(channelId) ?? Promise.resolve();
16:     const next = prev
17:       .then(async () => {
18:         const controller = new AbortController();
19:         this.running.set(channelId, controller);
20:         try {
21:           await job({ signal: controller.signal });
22:         } finally {
23:           if (this.running.get(channelId) === controller) {
24:             this.running.delete(channelId);
25:           }
26:         }
27:       })
28:       .catch((err) => {
29:         console.error(`[discord-bot] queue error on ${channelId}:`, err);
30:       });
31: 
32:     this.tails.set(channelId, next);
33:     void next.finally(() => {
34:       if (this.tails.get(channelId) === next) this.tails.delete(channelId);
35:     });
36:     return next;
37:   }
38: 
39:   /** Doc sent something new: stop waiting between her old bubbles. */
40:   abort(channelId: string): void {
41:     this.running.get(channelId)?.abort();
42:   }
43: 
44:   abortAll(): void {
45:     for (const controller of this.running.values()) controller.abort();
46:   }
47: 
48:   get activeCount(): number {
49:     return this.tails.size;
50:   }
51: 
52:   /** Shutdown: let in-flight deliveries land, but do not hang a deploy on them. */
53:   async drain(timeoutMs: number): Promise<void> {
54:     const tails = [...this.tails.values()];
55:     if (tails.length === 0) return;
56:     await Promise.race([
57:       Promise.allSettled(tails),
58:       new Promise((resolve) => setTimeout(resolve, timeoutMs)),
59:     ]);
60:   }
61: }
62: 
63: export const channelQueue = new ChannelQueue();
